import{_ as a,o as t,c as s,aj as i}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"en/installation.md","filePath":"en/installation.md"}'),n={name:"en/installation.md"};function l(o,e,r,p,h,c){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Get started with Angular quickly with online starters or locally with your terminal.</p><h2 id="play-online" tabindex="-1">Play Online <a class="header-anchor" href="#play-online" aria-label="Permalink to &quot;Play Online&quot;">​</a></h2><p>If you just want to play around with Angular in your browser without setting up a project, you can use our online sandbox:</p><ul><li><a href="https://angular.dev/playground" target="_blank" rel="noreferrer"><strong>Playground</strong></a>: The fastest way to play with an Angular app. No setup required.</li></ul><h2 id="set-up-a-new-project-locally" tabindex="-1">Set up a new project locally <a class="header-anchor" href="#set-up-a-new-project-locally" aria-label="Permalink to &quot;Set up a new project locally&quot;">​</a></h2><p>If you&#39;re starting a new project, you&#39;ll most likely want to create a local project so that you can use tooling such as Git.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li><strong>Node.js</strong> - <a href="/en/reference/versions">v22.22.3 or newer</a></li><li><strong>Text editor</strong> - We recommend <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a></li><li><strong>Terminal</strong> - Required for running <a href="/en/tools/cli">Angular CLI</a> commands</li><li><strong>Development Tool</strong> - To improve your development workflow, we recommend the <a href="/en/tools/language-service">Angular Language Service</a></li></ul><h3 id="instructions" tabindex="-1">Instructions <a class="header-anchor" href="#instructions" aria-label="Permalink to &quot;Instructions&quot;">​</a></h3><p>The following guide will walk you through setting up a local Angular project.</p><h4 id="install-angular-cli" tabindex="-1">Install Angular CLI <a class="header-anchor" href="#install-angular-cli" aria-label="Permalink to &quot;Install Angular CLI&quot;">​</a></h4><p>Open a terminal (if you&#39;re using <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a>, you can open an <a href="https://code.visualstudio.com/docs/editor/integrated-terminal" target="_blank" rel="noreferrer">integrated terminal</a>) and run the following command:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-N8FIQ" id="tab-PcfiCvt" checked><label data-title="npm" for="tab-PcfiCvt">npm</label><input type="radio" name="group-N8FIQ" id="tab-IHK-kng"><label data-title="pnpm" for="tab-IHK-kng">pnpm</label><input type="radio" name="group-N8FIQ" id="tab-IxIbzWn"><label data-title="yarn" for="tab-IxIbzWn">yarn</label><input type="radio" name="group-N8FIQ" id="tab-fPQ3RlF"><label data-title="bun" for="tab-fPQ3RlF">bun</label></div><div class="blocks"><div class="language-shell vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/cli</span></span></code></pre></div></div></div><p>If you are having issues running this command in Windows or Unix, check out the <a href="/en/tools/cli/setup-local#install-the-angular-cli">CLI docs</a> for more info.</p><h4 id="create-a-new-project" tabindex="-1">Create a new project <a class="header-anchor" href="#create-a-new-project" aria-label="Permalink to &quot;Create a new project&quot;">​</a></h4><p>In your terminal, run the CLI command <a href="https://angular.dev/cli/new" target="_blank" rel="noreferrer"><code>ng new</code></a> with the desired project name. In the following examples, we&#39;ll be using the example project name of <code>my-first-angular-app</code>.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">project-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>You will be presented with some configuration options for your project. Use the arrow and enter keys to navigate and select which options you desire.</p><p>If you don&#39;t have any preferences, just hit the enter key to take the default options and continue with the setup.</p><p>After you select the configuration options and the CLI runs through the setup, you should see the following message:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✔ Packages installed successfully.</span></span>
<span class="line"><span>    Successfully initialized git.</span></span></code></pre></div><p>At this point, you&#39;re now ready to run your project locally!</p><h4 id="running-your-new-project-locally" tabindex="-1">Running your new project locally <a class="header-anchor" href="#running-your-new-project-locally" aria-label="Permalink to &quot;Running your new project locally&quot;">​</a></h4><p>In your terminal, switch to your new Angular project.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-first-angular-app</span></span></code></pre></div><p>All of your dependencies should be installed at this point (which you can verify by checking for the existence of a <code>node_modules</code> folder in your project), so you can start your project by running the command:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>If everything is successful, you should see a similar confirmation message in your terminal:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Watch mode enabled. Watching for file changes...</span></span>
<span class="line"><span>NOTE: Raw file sizes do not reflect development server per-request transformations.</span></span>
<span class="line"><span>  ➜  Local:   http://localhost:4200/</span></span>
<span class="line"><span>  ➜  press h + enter to show help</span></span></code></pre></div><p>And now you can visit the path in <code>Local</code> (e.g., <code>http://localhost:4200</code>) to see your application. Happy coding! 🎉</p><h3 id="using-ai-for-development" tabindex="-1">Using AI for Development <a class="header-anchor" href="#using-ai-for-development" aria-label="Permalink to &quot;Using AI for Development&quot;">​</a></h3><p>To get started with building in your preferred AI powered IDE, <a href="/en/ai/develop-with-ai">check out Angular prompt rules and best practices</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Now that you&#39;ve created your Angular project, you can learn more about Angular in our <a href="/en/essentials">Essentials guide</a> or choose a topic in our in-depth guides!</p>`,35)]))}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
